-- #139 계정 제한 (ADR-0069 decision 1 #57-12…#57-15, decision 3 #37-8, #37-9, decision 4 #139 and
-- #140 rows; ADR-0056 decision 1-7; ADR-0085). Generated by `drizzle-kit generate`, then hand-edited
-- where marked: this header and the tail. The snapshot is as generated. Self-contained and additive
-- on #187's 0041: no row changes.
--
-- - report_reason: 이상 거래 (`abnormal_trading`) and 다계정 (`multi_account`), the two reasons only
--   an account restriction takes (#57-12), added at the end with ADD VALUE — so nothing in this
--   batch names them as the enum (55P04, migration 0014): the CHECKs below compare `reason::text`.
-- - reports_reason_check: a report's reason stays one of the report reasons (#45-10).
-- - moderation_actions.type: `account_restriction` joins the list (the CHECK replaced, as 0040 did).
--   Its subject is a writing restriction's (a post or a comment at most), its end too (the CHECKs
--   widened), its reason one of the owner's list for it with the explanation required
--   (moderation_actions_reason_check), and every other action's reason a report reason.
-- - moderation_actions.approval_id, cancel_approval_id and restriction_end_changes.approval_id:
--   the approvals (approval_requests, #171) an account restriction, its cancellation and each
--   change of its end came in by — exactly those (the CHECK and the triggers below), each approval
--   used once (UNIQUE).
-- - moderation_actions_standing_account_restriction_idx: a member's account restrictions not
--   cancelled, which an order (#119), a market proposal (#77), 탈퇴 (#140) and every new value of a
--   public profile item ask.
-- - approval_requests_target_idx and approval_requests_pending_requested_at_idx: a member's and a
--   restriction's requests, and the queue of requests waiting for a decision.
-- - approval_status: `retracted` (owner decision 2026-10-23, ADR-0085), added at the end with ADD
--   VALUE: a request its requester retracted before any decision — closed with no decision, decided
--   by no one, at approval_requests.retracted_at. approval_requests_decision_check is replaced
--   (compared as text, as above): the decision columns are null exactly while pending and once
--   retracted, and retracted_at is set exactly when retracted. Migration 0021's triggers already
--   keep a row no longer pending from any change, and a pending row's request columns as they are.
ALTER TYPE "public"."approval_status" ADD VALUE 'retracted';--> statement-breakpoint
ALTER TYPE "public"."report_reason" ADD VALUE 'abnormal_trading';--> statement-breakpoint
ALTER TYPE "public"."report_reason" ADD VALUE 'multi_account';--> statement-breakpoint
ALTER TABLE "approval_requests" DROP CONSTRAINT "approval_requests_decision_check";--> statement-breakpoint
ALTER TABLE "moderation_actions" DROP CONSTRAINT "moderation_actions_type_check";--> statement-breakpoint
ALTER TABLE "moderation_actions" DROP CONSTRAINT "moderation_actions_subject_check";--> statement-breakpoint
ALTER TABLE "moderation_actions" DROP CONSTRAINT "moderation_actions_ends_at_check";--> statement-breakpoint
ALTER TABLE "approval_requests" ADD COLUMN "retracted_at" timestamp (3) with time zone;--> statement-breakpoint
ALTER TABLE "moderation_actions" ADD COLUMN "approval_id" uuid;--> statement-breakpoint
ALTER TABLE "moderation_actions" ADD COLUMN "cancel_approval_id" uuid;--> statement-breakpoint
ALTER TABLE "restriction_end_changes" ADD COLUMN "approval_id" uuid;--> statement-breakpoint
ALTER TABLE "moderation_actions" ADD CONSTRAINT "moderation_actions_approval_id_approval_requests_id_fk" FOREIGN KEY ("approval_id") REFERENCES "public"."approval_requests"("id") ON DELETE restrict ON UPDATE no action;--> statement-breakpoint
ALTER TABLE "moderation_actions" ADD CONSTRAINT "moderation_actions_cancel_approval_id_approval_requests_id_fk" FOREIGN KEY ("cancel_approval_id") REFERENCES "public"."approval_requests"("id") ON DELETE restrict ON UPDATE no action;--> statement-breakpoint
ALTER TABLE "restriction_end_changes" ADD CONSTRAINT "restriction_end_changes_approval_id_approval_requests_id_fk" FOREIGN KEY ("approval_id") REFERENCES "public"."approval_requests"("id") ON DELETE restrict ON UPDATE no action;--> statement-breakpoint
CREATE INDEX "approval_requests_target_idx" ON "approval_requests" USING btree ("target_type","target_id");--> statement-breakpoint
CREATE INDEX "approval_requests_pending_requested_at_idx" ON "approval_requests" USING btree ("requested_at","id") WHERE "approval_requests"."status" = 'pending';--> statement-breakpoint
CREATE INDEX "moderation_actions_standing_account_restriction_idx" ON "moderation_actions" USING btree ("user_id","ends_at") WHERE "moderation_actions"."type" = 'account_restriction' AND "moderation_actions"."cancelled_at" IS NULL;--> statement-breakpoint
ALTER TABLE "moderation_actions" ADD CONSTRAINT "moderation_actions_approval_id_unique" UNIQUE("approval_id");--> statement-breakpoint
ALTER TABLE "moderation_actions" ADD CONSTRAINT "moderation_actions_cancel_approval_id_unique" UNIQUE("cancel_approval_id");--> statement-breakpoint
ALTER TABLE "restriction_end_changes" ADD CONSTRAINT "restriction_end_changes_approval_id_unique" UNIQUE("approval_id");--> statement-breakpoint
ALTER TABLE "approval_requests" ADD CONSTRAINT "approval_requests_decision_check" CHECK (("approval_requests"."status"::text IN ('pending', 'retracted')) = ("approval_requests"."decided_by" IS NULL) AND ("approval_requests"."decided_by" IS NULL) = ("approval_requests"."decided_at" IS NULL) AND ("approval_requests"."decided_by" IS NULL) = ("approval_requests"."decision_reason" IS NULL) AND ("approval_requests"."status"::text = 'retracted') = ("approval_requests"."retracted_at" IS NOT NULL));--> statement-breakpoint
ALTER TABLE "moderation_actions" ADD CONSTRAINT "moderation_actions_reason_check" CHECK (CASE WHEN "moderation_actions"."type" = 'account_restriction' THEN "moderation_actions"."reason"::text IN ('spam', 'harassment', 'personal_info', 'impersonation', 'collusion_manipulation', 'abnormal_trading', 'multi_account', 'other') AND "moderation_actions"."note" IS NOT NULL ELSE "moderation_actions"."reason"::text IN ('spam', 'harassment', 'personal_info', 'impersonation', 'collusion_manipulation', 'off_topic', 'rights_infringement', 'other') END);--> statement-breakpoint
ALTER TABLE "moderation_actions" ADD CONSTRAINT "moderation_actions_approval_check" CHECK (("moderation_actions"."type" = 'account_restriction') = ("moderation_actions"."approval_id" IS NOT NULL) AND ("moderation_actions"."type" = 'account_restriction' AND "moderation_actions"."cancelled_at" IS NOT NULL) = ("moderation_actions"."cancel_approval_id" IS NOT NULL));--> statement-breakpoint
ALTER TABLE "moderation_actions" ADD CONSTRAINT "moderation_actions_type_check" CHECK ("moderation_actions"."type" IN ('hide', 'warning', 'nickname_reset', 'bio_clear', 'image_remove', 'writing_restriction', 'account_restriction'));--> statement-breakpoint
ALTER TABLE "moderation_actions" ADD CONSTRAINT "moderation_actions_subject_check" CHECK (CASE "moderation_actions"."type" WHEN 'hide' THEN num_nonnulls("moderation_actions"."post_id", "moderation_actions"."comment_id") = 1 WHEN 'warning' THEN num_nonnulls("moderation_actions"."post_id", "moderation_actions"."comment_id") <= 1 WHEN 'writing_restriction' THEN num_nonnulls("moderation_actions"."post_id", "moderation_actions"."comment_id") <= 1 WHEN 'account_restriction' THEN num_nonnulls("moderation_actions"."post_id", "moderation_actions"."comment_id") <= 1 ELSE num_nonnulls("moderation_actions"."post_id", "moderation_actions"."comment_id") = 0 END);--> statement-breakpoint
ALTER TABLE "moderation_actions" ADD CONSTRAINT "moderation_actions_ends_at_check" CHECK ("moderation_actions"."ends_at" IS NULL OR ("moderation_actions"."type" IN ('writing_restriction', 'account_restriction') AND "moderation_actions"."ends_at" >= "moderation_actions"."created_at"));--> statement-breakpoint
ALTER TABLE "reports" ADD CONSTRAINT "reports_reason_check" CHECK ("reports"."reason"::text IN ('spam', 'harassment', 'personal_info', 'impersonation', 'collusion_manipulation', 'off_topic', 'rights_infringement', 'other'));--> statement-breakpoint
-- Hand-edited: whether `approval` is a request of `approval_kind` about the target named, asked for
-- by `asked_by` and approved by an admin who is not `member` (decision 4 #50 «다른 운영자만»: nobody
-- approves a restriction of themselves). The request's own triggers (migration 0021) hold the rest
-- of the two-person rule: decided once, by an admin at the time, never by its requester.
CREATE FUNCTION account_restriction_approved(
  approval uuid, approval_kind text, asked_by text, member text, target text, target_key text
) RETURNS boolean
LANGUAGE sql STABLE AS $$
  SELECT EXISTS (
    SELECT FROM "approval_requests"
     WHERE "id" = approval
       AND "kind" = approval_kind
       AND "status" = 'approved'
       AND "requested_by" = asked_by
       AND "decided_by" <> member
       AND "target_type" = target
       AND "target_id" = target_key)
$$;--> statement-breakpoint
-- Hand-edited: an account restriction comes into force only by another admin's approval of a
-- request for it (ADR-0056 decision 1-7, #57-12 «걸기와 풀기에는 다른 운영자의 승인»), whoever
-- writes: the approval names this member, the operator the row names as its own and the kind
-- `account_restriction`. One inserted cancelled names its cancellation's approval as well.
CREATE FUNCTION moderation_actions_approved() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF NEW.type = 'account_restriction' THEN
    IF NOT account_restriction_approved(NEW.approval_id, 'account_restriction', NEW.created_by,
                                        NEW.user_id, 'user', NEW.user_id) THEN
      RAISE EXCEPTION 'account restriction % needs another admin''s approval of its request', NEW.id
        USING ERRCODE = 'integrity_constraint_violation';
    END IF;
    IF NEW.cancelled_at IS NOT NULL
       AND NOT account_restriction_approved(NEW.cancel_approval_id, 'account_restriction_cancel',
                                            NEW.cancelled_by, NEW.user_id, 'moderation_action',
                                            NEW.id::text) THEN
      RAISE EXCEPTION 'account restriction % is cancelled only by an approved request', NEW.id
        USING ERRCODE = 'integrity_constraint_violation';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;--> statement-breakpoint
CREATE TRIGGER moderation_actions_approved
  BEFORE INSERT ON "moderation_actions"
  FOR EACH ROW EXECUTE FUNCTION moderation_actions_approved();--> statement-breakpoint
-- Hand-edited: as migration 0040 left it, and an account restriction's end opens the same way as a
-- writing restriction's — forward only while it stands, never back, never to 무기한, never with a
-- cancellation (its approval is held below and by restriction_end_changes' trigger). The approval
-- that put it in force never changes, and its cancellation comes only with another admin's approval
-- of a request to cancel this restriction (ADR-0056 decision 1-7).
CREATE OR REPLACE FUNCTION moderation_actions_keep_record() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF OLD.cancelled_at IS NOT NULL THEN
    RAISE EXCEPTION 'moderation action % was cancelled and cannot change', OLD.id
      USING ERRCODE = 'integrity_constraint_violation';
  END IF;
  IF (NEW.id, NEW.type, NEW.user_id, NEW.post_id, NEW.comment_id, NEW.reason, NEW.note,
      NEW.created_by, NEW.created_at, NEW.approval_id)
     IS DISTINCT FROM
     (OLD.id, OLD.type, OLD.user_id, OLD.post_id, OLD.comment_id, OLD.reason, OLD.note,
      OLD.created_by, OLD.created_at, OLD.approval_id) THEN
    RAISE EXCEPTION 'moderation action % cannot change what was done', OLD.id
      USING ERRCODE = 'integrity_constraint_violation';
  END IF;
  IF NEW.ends_at IS DISTINCT FROM OLD.ends_at THEN
    IF OLD.type NOT IN ('writing_restriction', 'account_restriction')
       OR NEW.ends_at IS NULL
       OR NEW.ends_at < date_trunc('milliseconds', now())
       OR (OLD.ends_at IS NOT NULL AND (NEW.ends_at >= OLD.ends_at OR OLD.ends_at <= now()))
       OR NEW.cancelled_at IS NOT NULL THEN
      RAISE EXCEPTION 'moderation action % only brings a standing restriction''s end forward', OLD.id
        USING ERRCODE = 'integrity_constraint_violation';
    END IF;
  END IF;
  IF NEW.cancelled_at IS NOT NULL AND NEW.type = 'account_restriction'
     AND NOT account_restriction_approved(NEW.cancel_approval_id, 'account_restriction_cancel',
                                          NEW.cancelled_by, NEW.user_id, 'moderation_action',
                                          NEW.id::text) THEN
    RAISE EXCEPTION 'account restriction % is cancelled only by an approved request', OLD.id
      USING ERRCODE = 'integrity_constraint_violation';
  END IF;
  RETURN NEW;
END;
$$;--> statement-breakpoint
-- Hand-edited: a change of an account restriction's end (감경, 조기 해제) is the asking operator's,
-- in force only by another admin's approval of a request of its kind for this restriction
-- (`account_restriction_shorten`, `account_restriction_lift`); a writing restriction's change names
-- no approval (#185: no approval for it).
CREATE FUNCTION restriction_end_changes_approved() RETURNS trigger
LANGUAGE plpgsql AS $$
DECLARE
  action_type varchar;
  member text;
BEGIN
  SELECT "type", "user_id" INTO action_type, member
    FROM "moderation_actions" WHERE "id" = NEW.action_id;
  IF action_type = 'account_restriction' THEN
    IF NOT account_restriction_approved(NEW.approval_id, 'account_restriction_' || NEW.kind,
                                        NEW.created_by, member, 'moderation_action',
                                        NEW.action_id::text) THEN
      RAISE EXCEPTION 'a change of account restriction % needs another admin''s approval',
        NEW.action_id
        USING ERRCODE = 'integrity_constraint_violation';
    END IF;
  ELSIF NEW.approval_id IS NOT NULL THEN
    RAISE EXCEPTION 'only an account restriction''s change names an approval'
      USING ERRCODE = 'integrity_constraint_violation';
  END IF;
  RETURN NEW;
END;
$$;--> statement-breakpoint
CREATE TRIGGER restriction_end_changes_approved
  BEFORE INSERT ON "restriction_end_changes"
  FOR EACH ROW EXECUTE FUNCTION restriction_end_changes_approved();--> statement-breakpoint
-- Hand-edited: an account restriction's end moves only with its change row — the approved one above
-- — so, at the commit, the end it has is the end its latest change gave (the earliest of them: each
-- change brings it strictly forward). Deferred, as the change row is written after the end, in the
-- same transaction. A writing restriction's end is left as migration 0040 left it.
CREATE FUNCTION moderation_actions_account_end_changed() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF NEW.type = 'account_restriction'
     AND (SELECT "ends_at" FROM "moderation_actions" WHERE "id" = NEW.id)
         IS DISTINCT FROM
         (SELECT min("ends_at") FROM "restriction_end_changes" WHERE "action_id" = NEW.id) THEN
    RAISE EXCEPTION 'account restriction % changes its end only with an approved change', NEW.id
      USING ERRCODE = 'integrity_constraint_violation';
  END IF;
  RETURN NULL;
END;
$$;--> statement-breakpoint
CREATE CONSTRAINT TRIGGER moderation_actions_account_end_changed
  AFTER UPDATE OF "ends_at" ON "moderation_actions"
  DEFERRABLE INITIALLY DEFERRED
  FOR EACH ROW
  WHEN (OLD.ends_at IS DISTINCT FROM NEW.ends_at)
  EXECUTE FUNCTION moderation_actions_account_end_changed();
